const sanitize = require('./sanitize');

// ---- Test 4: unbounded recursion on nested input ----
function deepJson(n) {
  return '{"a":'.repeat(n) + '"x"' + '}'.repeat(n);
}
for (const depth of [1000, 5000, 10000, 20000]) {
  const payload = deepJson(depth);
  let parsed;
  try { parsed = JSON.parse(payload); } catch (e) { console.log(depth, 'JSON.parse failed:', e.message); continue; }
  try {
    sanitize(parsed);
    console.log(`depth=${depth} bytes=${payload.length} -> ok`);
  } catch (e) {
    console.log(`depth=${depth} bytes=${payload.length} -> THROWS ${e.constructor.name}: ${e.message.slice(0,60)}`);
  }
}

// ---- Test 5: does traversal pollute Object.prototype? ----
const p = JSON.parse('{"__proto__":{"polluted":"yes"},"constructor":{"x":"y"}}');
sanitize(p);
console.log('T5 Object.prototype.polluted =', ({}).polluted);
console.log('T5 own __proto__ still own?', Object.getOwnPropertyNames(p));
EOF
node t3.js

